### Python Script (FastAPI with Background Worker)

```python
import threading
import queue
import psutil
from fastapi import FastAPI
from starlette.responses import JSONResponse
import signal
import sys

app = FastAPI()
queue = queue.Queue()

def hardware_state():
    """Collects and returns the current RAM/VRAM usage."""
    ram_usage = psutil.virtual_memory().percent
    # Assuming VRAM is not directly accessible via psutil, we simulate it here.
    vram_usage = 0  # Replace with actual VRAM monitoring logic if available.
    return {"RAM_Usage": ram_usage, "VRAM_Usage": vram_usage}

def background_worker():
    """Background worker that periodically updates the hardware state in the queue."""
    while True:
        try:
            queue.put(hardware_state(), timeout=5)
        except queue.Full:
            continue

@app.get("/api/health")
async def health():
    """Endpoint to report active hardware state."""
    return JSONResponse(content=queue.get_nowait())

def signal_handler(sig):
    """Graceful shutdown handler for SIGINT and SIGTERM."""
    print(f"Received termination signal {sig}. Shutting down...")
    sys.exit(0)

if __name__ == "__main__":
    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Start the background worker thread
    worker_thread = threading.Thread(target=background_worker, daemon=True)
    worker_thread.start()

    # Run FastAPI server
    from fastapi import FastAPI
    app.run(host="0.0.0.0", port=8000)
```

### Node.js Snippet for Spawning the Process and Polling `/api/health`

```javascript
const { spawn } = require('child_process');
const fetch = require('node-fetch');
const os = require('os');

// Function to simulate exponential backoff
function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function pollHealthEndpoint(url, maxAttempts = 10) {
    let attempt = 0;
    while (attempt < maxAttempts) {
        try {
            const response = await fetch(`${url}/api/health`);
            if (response.ok) {
                const data = await response.json();
                console.log('Health check passed:', data);
                return data; // Return the hardware state
            } else {
                throw new Error(`HTTP error ${response.status}`);
            }
        } catch (error) {
            attempt++;
            console.error(`Attempt ${attempt} failed: ${error.message}. Retrying...`);
            await sleep((2 ** attempt) * 1000); // Exponential backoff
        }
    }
    throw new Error('Max attempts reached. Health check failed.');
}

// Spawn the Python FastAPI process
const pythonProcess = spawn('python', ['sidecar_engine.py'], { stdio: 'inherit' });

// Function to handle unexpected termination of the child process
function onChildExit(code, signal) {
    if (code !== 0) {
        console.error(`Python process exited with code ${code}`);
    } else if (signal) {
        console.error(`Python process terminated by signal ${signal}`);
    }
}

pythonProcess.on('exit', onChildExit);

// Poll the health endpoint
(async () => {
    try {
        const url = 'http://localhost:8000'; // Adjust based on your setup
        await pollHealthEndpoint(url);
    } catch (error) {
        console.error(error.message);
    }
})();
```

### Explanation

1. **Python Script**:
   - Uses FastAPI to create a web server.
   - Implements a background worker thread that periodically updates the hardware state in a thread-safe queue.
   - Provides an `/api/health` endpoint to report the active hardware state (RAM usage is fetched using `psutil`; VRAM usage is simulated).
   - Handles SIGINT and SIGTERM signals for graceful shutdown.

2. **Node.js Snippet**:
   - Spawns the Python FastAPI process using Node's `child_process.spawn`.
   - Implements a polling function with exponential backoff to check the `/api/health` endpoint until it responds successfully.
   - Includes error handling for unexpected termination of the child process and logs appropriate messages.

This setup ensures that the sidecar engine runs in the background, reports its health status, and can be gracefully shut down. The Node.js snippet safely manages the lifecycle of the Python process and handles communication with the `/api/health` endpoint robustly.
